<?php require __DIR__.'/bootstrap.php';
$p=db();$one=fn($sql)=>(int)$p->query($sql)->fetchColumn();$last=$p->query('SELECT MAX(executed_at) FROM monitor_logs')->fetchColumn();$hours=(int)($p->query("SELECT setting_value FROM settings WHERE setting_key='monitor_stale_hours'")->fetchColumn()?:24);$latest=$p->query("SELECT * FROM news WHERE relevance_status='related' ORDER BY published_at DESC,discovered_at DESC LIMIT 8")->fetchAll();
respond(['total'=>$one('SELECT COUNT(*) FROM news'),'new_count'=>$one('SELECT COUNT(*) FROM news WHERE is_new=1'),'today'=>$one('SELECT COUNT(*) FROM news WHERE DATE(discovered_at)=CURDATE()'),'last_7_days'=>$one('SELECT COUNT(*) FROM news WHERE discovered_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)'),'related'=>$one("SELECT COUNT(*) FROM news WHERE relevance_status='related'"),'review'=>$one("SELECT COUNT(*) FROM news WHERE relevance_status IN ('possibly_related','manual_review')"),'unrelated'=>$one("SELECT COUNT(*) FROM news WHERE relevance_status='unrelated'"),'active_sources'=>$one('SELECT COUNT(*) FROM sources WHERE active=1'),'active_terms'=>$one('SELECT COUNT(*) FROM search_terms WHERE active=1'),'last_run'=>$last,'monitor_ok'=>$last&&strtotime($last)>time()-$hours*3600,'latest'=>$latest]);
